# core.py —— 训练 / 评估门禁 / 保存载入（joblib）

def train(X, y, test_size=0.25, seed=42):
    Xtr, Xte, ytr, yte = train_test_split(
        X, y, test_size=test_size,
        stratify=y, random_state=seed)
    m = RandomForestClassifier(
        n_estimators=100, random_state=0).fit(Xtr, ytr)
    return m, {"macro_f1": f1_score(yte, m.predict(Xte),
                        average="macro")}

def gate(metrics, min_f1=0.80):
    """评估门禁：macro-F1 低于阈值即不通过"""
    return metrics["macro_f1"] >= min_f1

def save_model(model, path, metrics):
    os.makedirs(os.path.dirname(os.path.abspath(path)),
                exist_ok=True)
    joblib.dump(model, path); return path

def test_gate_pass(metrics):
    assert gate(metrics, min_f1=0.80) is True

def test_gate_fail(metrics):
    low = {"macro_f1": 0.55}
    assert gate(low, min_f1=0.80) is False

